using System.Drawing;using Forms=System.Windows.Forms;namespace OdinVault.Manager.Wpf.Services;internal sealed class TrayService:IDisposable{readonly Forms.NotifyIcon icon;readonly Action show;public TrayService(Action showWindow,Action exit){show=showWindow;var menu=new Forms.ContextMenuStrip();menu.Items.Add("باز کردن OdinVault",null,(_,_)=>show());menu.Items.Add("خروج",null,(_,_)=>exit());icon=new Forms.NotifyIcon{Text="OdinVault Manager",Icon=SystemIcons.Shield,Visible=true,ContextMenuStrip=menu};icon.DoubleClick+=(_,_)=>show();}public void Notify(string title,string text){icon.BalloonTipTitle=title;icon.BalloonTipText=text;icon.ShowBalloonTip(3500);}public void Dispose(){icon.Visible=false;icon.Dispose();}}